import { useMemo, useState } from "react";

type Item = { id: string; price: number; qty: number };

function CartTotal({ items }: { items: Item[] }) {
  const [taxRate, setTaxRate] = useState(0.2);

  const total = useMemo(() => {
    return items.reduce((sum, item) => sum + item.price * item.qty, 0);
  }, [items]);

  const totalWithTax = useMemo(
    () => total * (1 + taxRate),
    [total, taxRate],
  );

  return (
    <p>
      Subtotal {total.toFixed(2)} / Total {totalWithTax.toFixed(2)}
    </p>
  );
}

